    std::array<float, 2> ui_pointer_position() noexcept {
        if (!g_session.open) {
            return {0.0f, 0.0f};
        }
        const glm::vec2 position = g_session.context->pointer_position();
        return {position.x, position.y};
    }

    bool ui_pointer_is_down() noexcept {
        return g_session.open && g_session.context->pointer_is_down();
    }

    UiPointerSnapshot ui_pointer_state(const EngineView &engine) noexcept {
        const E::UiPointerState &pointer = engine.ui_pointer_state();
        const SFT::UI::PointerState &state = pointer.state();
        UiPointerSnapshot snapshot{};
        snapshot.position = {state.position.x, state.position.y};
        snapshot.down = state.down;
        snapshot.pressed_this_frame = state.pressed;
        snapshot.released_this_frame = state.released;
        snapshot.cancelled_this_frame = state.cancelled;
        snapshot.has_press_position = state.press_position.has_value();
        if (state.press_position) {
            snapshot.press_position = {state.press_position->x, state.press_position->y};
        } else {
            snapshot.press_position = {0.0f, 0.0f};
        }
        snapshot.scroll_delta = {state.scroll_delta.x, state.scroll_delta.y};
        snapshot.consumed = pointer.consumed();
        return snapshot;
    }

    UiTextInputSnapshot ui_text_input_state(const EngineView &engine) {
        const E::UiTextInputState &input = engine.ui_text_input_state();
        const SFT::UI::TextEditInput frame_input = input.frame_input();
        UiTextInputSnapshot snapshot{};
        snapshot.typed_text = rust::String::lossy(frame_input.typed_text.data(), frame_input.typed_text.size());
        snapshot.composing = frame_input.composing;
        snapshot.composition_text =
            rust::String::lossy(frame_input.composition_text.data(), frame_input.composition_text.size());
        return snapshot;
    }

